/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_categories_after_delete` AFTER DELETE ON `tbc_categories` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description
    )
    VALUES (
        'tbc_categories',
        'Delete',
        USER(),
        CONCAT(
            'Categoría eliminada: "', OLD.name,
            '". ID: ', OLD.ID,
            ', Descripción: ', COALESCE(OLD.description, 'Sin descripción'),
            ', Categoría superior: ', COALESCE(OLD.sup_id_category, 'Sin categoría superior'),
            ', Estado: ', COALESCE(OLD.status, 0)
        )
    );
END */;;
